insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g1_ss_v1'
from (values
('113.12.c.1.A',2,'Which holiday celebrates the signing of the Declaration of Independence?','["Independence Day", "Memorial Day", "Labor Day", "Arbor Day"]'::jsonb,0,'Independence Day is July 4.','original'),
('113.12.c.1.A',2,'On Veterans Day, people honor...','["inventors of toys", "those who served in the military", "famous chefs", "sports stars"]'::jsonb,1,'Veterans Day honors military service.','original'),
('113.12.c.1.B',3,'Two families celebrate a holiday. One has a picnic, and the other has a parade. What does this show?','["only one way is allowed", "holidays are not real", "people observe holidays in different ways", "nobody celebrates"]'::jsonb,2,'Customs can differ.','original'),
('113.12.c.2.A',2,'Which leader helped Texas become a republic and later a state?','["Robin Hood", "Tom Sawyer", "Mickey Mouse", "Sam Houston"]'::jsonb,3,'Sam Houston was a leader of Texas.','original'),
('113.12.c.2.A',2,'Which leader led the nation during the Civil War and signed the Emancipation Proclamation?','["Abraham Lincoln", "Daniel Boone", "Johnny Appleseed", "Paul Revere"]'::jsonb,0,'Lincoln led the nation.','original'),
('113.12.c.2.A',2,'Which leader worked to end unfair treatment of Black Americans with peaceful marches and speeches?','["Benjamin Banneker", "Martin Luther King Jr.", "Sam Houston", "George Washington"]'::jsonb,1,'He led the civil rights movement.','original'),
('113.12.c.2.B',3,'How are George Washington and Abraham Lincoln alike?','["both lived in Texas", "both were astronauts", "both were Presidents of the United States", "both were inventors of the telephone"]'::jsonb,2,'Both led the nation.','original'),
('113.12.c.3.A',2,'You stand at the front of the class. Your friend is behind you. Where is your friend?','["in front of you", "above you", "inside you", "in back of you"]'::jsonb,3,'Behind means in back of.','original'),
('113.12.c.3.A',2,'The pencil box is next to the book. What does next to mean?','["beside it", "across the sea", "very far away", "under the world"]'::jsonb,0,'Next to means beside.','original'),
('113.12.c.3.B',2,'On a map, which direction is usually at the top?','["south", "north", "west", "east"]'::jsonb,1,'North is usually up.','original'),
('113.12.c.3.B',3,'If you walk toward the setting sun, which direction are you going?','["east", "south", "west", "north"]'::jsonb,2,'The sun sets in the west.','original'),
('113.12.c.3.B',3,'Which direction is opposite of south?','["down", "east", "west", "north"]'::jsonb,3,'North is opposite south.','original'),
('113.12.c.4.A',2,'What does a simple map of a classroom show?','["where furniture is", "who is the teacher", "the weather today", "what is for lunch"]'::jsonb,0,'A classroom map shows locations.','original'),
('113.12.c.4.A',2,'A map of your school shows the library near the gym. What does this help you do?','["choose a lunch", "find your way", "learn a song", "spell a word"]'::jsonb,1,'Maps help you find places.','original'),
('113.12.c.4.B',2,'Which tool shows the whole Earth as a ball?','["ruler", "clock", "globe", "calendar"]'::jsonb,2,'A globe is a model of Earth.','original'),
('113.12.c.4.B',3,'Which state is shown on a map of the United States where we live?','["Mars", "Atlantis", "Antarctica", "Texas"]'::jsonb,3,'Texas is one of the 50 states.','original'),
('113.12.c.5.A',2,'Which is weather?','["snowy", "plateau", "canyon", "river"]'::jsonb,0,'Snow is weather.','original'),
('113.12.c.5.B',3,'Why do people in hot places often wear light clothes?','["to stay warm in snow", "to stay cool", "to float", "to hide from rain"]'::jsonb,1,'Light clothes keep people cool.','original'),
('113.12.c.5.B',3,'Why might people near the ocean eat a lot of fish?','["there are no stores", "fish are in deserts", "fish live in the ocean nearby", "there are no people"]'::jsonb,2,'Location influences food.','original'),
('113.12.c.6.A',2,'Which way can a family meet the need for food?','["ignore it", "avoid eating", "ask the moon", "grow or buy it"]'::jsonb,3,'Families grow or buy food.','original'),
('113.12.c.6.A',2,'Which is a way a family can get shelter?','["build or rent a home", "dig only to China", "wait for a cloud", "float in the sky"]'::jsonb,0,'Shelter is a home.','original'),
('113.12.c.6.B',3,'One family grows vegetables. Another buys vegetables at a store. How are they alike?','["both are far away", "both meet the need for food", "both grow tomatoes", "both live in the same house"]'::jsonb,1,'Both meet a need.','original'),
('113.12.c.7.A',2,'Which is a good, not a service?','["a haircut", "a bus ride", "a toy", "a doctor visit"]'::jsonb,2,'A good is an item you can hold.','original'),
('113.12.c.7.A',2,'Which is a service?','["a book", "a toy", "a shoe", "a haircut"]'::jsonb,3,'A service is work done for someone.','original'),
('113.12.c.7.B',3,'How can people exchange goods?','["trade or buy", "break", "hide", "steal"]'::jsonb,0,'People trade goods for money or other goods.','original'),
('113.12.c.7.C',3,'Where can you buy groceries?','["a zoo cage", "a market", "a library book return", "a school bus"]'::jsonb,1,'Markets sell goods.','original'),
('113.12.c.8.A',2,'Mia wants a new bike, a game, and a kite but only has money for one. What is this?','["being lost", "having everything", "wanting more than she can have", "getting free toys"]'::jsonb,2,'Limited money.','original'),
('113.12.c.8.B',3,'Because people cannot have everything they want, they must...','["stop working", "get everything", "stop eating", "make choices"]'::jsonb,3,'Scarcity requires choices.','original'),
('113.12.c.8.C',3,'A family must choose between a new couch and a vacation. This is an example of...','["a family making a choice", "a free gift", "a family getting everything", "a family doing nothing"]'::jsonb,0,'They must pick one.','original'),
('113.12.c.9.A',2,'Which tool does a carpenter use?','["paintbrush", "hammer", "stethoscope", "whistle"]'::jsonb,1,'Carpenters build with hammers.','original'),
('113.12.c.9.A',2,'A job well done is...','["broken", "ignored", "careful and finished", "sloppy and late"]'::jsonb,2,'Good work is careful.','original'),
('113.12.c.9.B',3,'How does a farmer help make goods?','["builds roads", "flies planes", "teaches music", "grows food"]'::jsonb,3,'Farmers produce food.','original'),
('113.12.c.9.B',3,'Which job helps make a service?','["bus driver", "toy builder", "brick maker", "candle maker"]'::jsonb,0,'Drivers provide a service.','original'),
('113.12.c.10.A',2,'Why do rules and laws help a community?','["they make people sad", "they keep people safe and fair", "they cause trouble", "they stop everyone talking"]'::jsonb,1,'Rules protect people.','original'),
('113.12.c.10.A',2,'Which is a classroom rule?','["Shout anytime.", "Break pencils.", "Raise your hand to speak.", "Leave without asking."]'::jsonb,2,'Rules guide behavior.','original'),
('113.12.c.10.B',3,'A law says drivers must stop at red lights. What does this law provide?','["nothing", "noise", "candy", "safety"]'::jsonb,3,'Laws keep people safe.','original'),
('113.12.c.10.B',3,'When two students argue over a toy, a rule can help...','["manage the conflict", "start a fight", "ignore the problem", "break the toy"]'::jsonb,0,'Rules help settle disagreements.','original'),
('113.12.c.11.A',2,'Which person makes sure students are safe at school?','["clown", "principal", "bus mechanic", "pilot"]'::jsonb,1,'The principal oversees safety.','original'),
('113.12.c.11.A',2,'Who is responsible for keeping a child safe at home?','["the mailbox", "a stuffed toy", "a parent or caregiver", "a crossing sign"]'::jsonb,2,'Parents care for children.','original'),
('113.12.c.11.B',3,'Who is the leader of our state of Texas?','["librarian", "principal", "coach", "governor"]'::jsonb,3,'The governor leads the state.','original'),
('113.12.c.11.B',3,'Who is the leader of our whole country?','["President", "mayor", "teacher", "police chief"]'::jsonb,0,'The President leads the nation.','original'),
('113.12.c.11.B',3,'Who is the leader of a city or town?','["President", "mayor", "principal", "governor"]'::jsonb,1,'Mayors lead cities.','original'),
('113.12.c.12.A',2,'Which is a trait of a good citizen?','["being unkind", "breaking things", "being honest", "telling lies"]'::jsonb,2,'Honesty is a good trait.','original'),
('113.12.c.12.A',3,'A good citizen shows respect by...','["teasing", "interrupting", "taking turns away", "listening to others"]'::jsonb,3,'Respect includes listening.','original'),
('113.12.c.12.A',3,'Which is an example of responsibility?','["cleaning up your toys", "ignoring chores", "hiding homework", "leaving trash"]'::jsonb,0,'Responsibility means doing your part.','original'),
('113.12.c.12.B',3,'Benjamin Franklin is remembered as a good citizen because he...','["stayed alone", "helped his community with ideas and inventions", "only played games", "never helped anyone"]'::jsonb,1,'Franklin helped his community.','original'),
('113.12.c.12.B',3,'Eleanor Roosevelt is remembered for...','["building roller coasters", "selling candy", "helping people and speaking up for fairness", "making pizza"]'::jsonb,2,'She worked for human rights.','original'),
('113.12.c.13.A',2,'Which landmark is a symbol of freedom in New York?','["the Pyramids", "the Eiffel Tower", "the Great Wall", "Statue of Liberty"]'::jsonb,3,'The Statue of Liberty welcomed immigrants.','original'),
('113.12.c.13.A',2,'Which bell is a symbol of American independence?','["Liberty Bell", "doorbell", "school bell", "jingle bell"]'::jsonb,0,'The Liberty Bell is a patriotic symbol.','original'),
('113.12.c.13.A',2,'What is the Alamo a symbol of in Texas?','["a swimming pool", "bravery and the fight for freedom", "a shopping mall", "a zoo"]'::jsonb,1,'The Alamo is a Texas symbol.','original'),
('113.12.c.13.B',2,'What do you say to show respect to the United States flag?','["a bedtime story", "a happy birthday song", "the Pledge of Allegiance", "a lunch order"]'::jsonb,2,'The pledge honors the flag.','original'),
('113.12.c.13.C',3,'Which song is the national anthem of the United States?','["Happy Birthday", "Jingle Bells", "Twinkle Twinkle", "The Star-Spangled Banner"]'::jsonb,3,'It is the national anthem.','original'),
('113.12.c.13.C',3,'What is the motto printed on U.S. money?','["In God We Trust", "Go Team Go", "Fun for All", "Texas Forever"]'::jsonb,0,'It is the national motto.','original'),
('113.12.c.13.D',2,'The class votes for a field trip. How is the winner chosen?','["nobody decides", "the choice with the most votes", "the teacher flips a coin", "the choice with the fewest votes"]'::jsonb,1,'The most votes win.','original'),
('113.12.c.13.E',3,'Patriotic celebrations like parades show...','["fear of change", "silence", "pride in freedom", "boredom"]'::jsonb,2,'They celebrate American values.','original'),
('113.12.c.14.A',2,'Which tradition might a family share on a special holiday?','["a lost sock", "a missed bus", "a nap in the grocery store", "a special meal"]'::jsonb,3,'Traditions are repeated customs.','original'),
('113.12.c.14.B',3,'What do folktales often teach?','["a lesson about beliefs", "how to fix a car", "math homework only", "the weather forecast"]'::jsonb,0,'Folktales pass on values.','original'),
('113.12.c.15.A',2,'How has technology changed the way families live?','["it removes electricity", "washing machines save time", "it makes houses disappear", "it stops all work"]'::jsonb,1,'Machines help families.','original'),
('113.12.c.15.B',3,'Which invention helps people send messages to someone far away?','["comb", "spoon", "telephone", "pillow"]'::jsonb,2,'Telephones connect distant people.','original'),
('113.12.c.15.B',3,'How is traveling today different from long ago?','["there are no vehicles", "no one travels", "everyone walks only", "cars and planes are faster than horses"]'::jsonb,3,'Technology speeds travel.','original'),
('113.12.c.15.C',3,'Who invented a practical telephone?','["Alexander Graham Bell", "Benjamin Franklin", "Thomas Edison", "Garrett Morgan"]'::jsonb,0,'Bell is credited with the telephone.','original'),
('113.12.c.15.C',3,'Thomas Edison is famous for improving the...','["telescope", "light bulb", "airplane", "stove"]'::jsonb,1,'Edison improved the light bulb.','original'),
('113.12.c.15.C',3,'Garrett Morgan invented an early...','["laptop", "television", "traffic signal", "calculator"]'::jsonb,2,'Morgan invented a traffic signal.','original'),
('113.12.c.16.B',3,'Which is a primary source from long ago?','["a cartoon about the past", "a toy robot", "a snack bar", "an old diary"]'::jsonb,3,'A diary was written by someone who lived then.','original'),
('113.12.c.16.B',3,'A museum shows old tools and clothes. These objects are called...','["artifacts", "riddles", "songs", "stories"]'::jsonb,0,'Artifacts are old objects.','original'),
('113.12.c.16.D',2,'You sort pictures into animals and plants. This is...','["erasing", "categorizing", "guessing", "hiding"]'::jsonb,1,'Sorting into groups is categorizing.','original'),
('113.12.c.17.A',2,'On a timeline, which word tells about something that already happened?','["present", "never", "past", "future"]'::jsonb,2,'Past is before now.','original'),
('113.12.c.17.A',2,'On a timeline, what do we call right now?','["history", "future", "past", "present"]'::jsonb,3,'Present is now.','original'),
('113.12.c.17.B',2,'How many days are in a week?','["7", "10", "12", "5"]'::jsonb,0,'A week has seven days.','original'),
('113.12.c.17.B',2,'How many months are in a year?','["52", "12", "30", "7"]'::jsonb,1,'A year has twelve months.','original'),
('113.12.c.17.D',3,'A picture graph shows how many students like each fruit. What does it help you see?','["the time", "a story ending", "which fruit is liked most", "the weather"]'::jsonb,2,'Graphs compare data.','original'),
('113.12.c.17.E',2,'Which word means something that happened a long time ago?','["future", "tomorrow", "soon", "history"]'::jsonb,3,'History is about the past.','original'),
('113.12.c.18.A',2,'A class wants to choose a game. A fair way to decide is to...','["vote", "hide", "walk away", "argue"]'::jsonb,0,'Voting is democratic.','original'),
('113.12.c.18.B',3,'What is the first step in solving a problem?','["ignore it", "identify the problem", "hide it", "blame someone"]'::jsonb,1,'You must know the problem first.','original'),
('113.12.c.18.B',3,'After you gather information about a problem, you should...','["panic", "forget it", "list options", "quit"]'::jsonb,2,'List possible solutions.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
